// ===== ユーティリティ =====
const $ = (sel) => document.querySelector(sel);
const yen = (n) => "¥" + n.toLocaleString("ja-JP");
const escapeHtml = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

// ===== カート（localStorage に保存） =====
const Cart = {
  key: "shopeasy_cart",
  load() {
    try { return JSON.parse(localStorage.getItem(this.key)) || []; } catch { return []; }
  },
  save(items) {
    localStorage.setItem(this.key, JSON.stringify(items));
    updateCartBadge();
  },
  add(productId, qty = 1) {
    const product = PRODUCTS.find((p) => p.id === productId);
    if (!product) return;
    const items = this.load();
    const existing = items.find((i) => i.id === productId);
    const currentQty = existing ? existing.qty : 0;
    if (currentQty + qty > product.stock) {
      showToast("在庫数を超えています");
      return;
    }
    if (existing) existing.qty += qty;
    else items.push({ id: productId, qty });
    this.save(items);
    showToast(`「${product.name}」をカートに追加しました`);
  },
  setQty(productId, qty) {
    const product = PRODUCTS.find((p) => p.id === productId);
    let items = this.load();
    if (qty <= 0) items = items.filter((i) => i.id !== productId);
    else {
      if (product && qty > product.stock) { showToast("在庫数を超えています"); return; }
      const item = items.find((i) => i.id === productId);
      if (item) item.qty = qty;
    }
    this.save(items);
  },
  remove(productId) {
    this.save(this.load().filter((i) => i.id !== productId));
  },
  clear() { this.save([]); },
  detailed() {
    return this.load()
      .map((i) => {
        const product = PRODUCTS.find((p) => p.id === i.id);
        return product ? { ...product, qty: i.qty } : null;
      })
      .filter(Boolean);
  },
  count() { return this.load().reduce((sum, i) => sum + i.qty, 0); },
  subtotal() { return this.detailed().reduce((sum, p) => sum + p.price * p.qty, 0); },
  shipping() {
    const sub = this.subtotal();
    return sub === 0 || sub >= FREE_SHIPPING_THRESHOLD ? 0 : SHIPPING_FEE;
  }
};

function updateCartBadge() {
  $("#cart-count").textContent = Cart.count();
}

let toastTimer;
function showToast(message) {
  const el = $("#toast");
  el.textContent = message;
  el.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove("show"), 2200);
}

// ===== 描画 =====
function renderCategoryNav(active = "すべて") {
  $("#category-nav").innerHTML = CATEGORIES.map(
    (c) => `<a href="#/?category=${encodeURIComponent(c)}" class="${c === active ? "active" : ""}">${escapeHtml(c)}</a>`
  ).join("");
}

function productCard(p) {
  const soldOut = p.stock <= 0;
  return `
    <article class="product-card">
      <a href="#/product/${p.id}" class="product-thumb">${p.image}</a>
      <div class="product-info">
        <a href="#/product/${p.id}" class="product-name">${escapeHtml(p.name)}</a>
        <p class="muted small">${escapeHtml(p.category)}</p>
        <p class="price">${yen(p.price)}</p>
        <button class="btn btn-primary" data-add="${p.id}" ${soldOut ? "disabled" : ""}>
          ${soldOut ? "在庫切れ" : "カートに入れる"}
        </button>
      </div>
    </article>`;
}

function renderHome(params) {
  const category = params.get("category") || "すべて";
  const query = (params.get("q") || "").trim().toLowerCase();
  renderCategoryNav(category);

  let list = PRODUCTS;
  if (category !== "すべて") list = list.filter((p) => p.category === category);
  if (query) list = list.filter((p) => (p.name + p.description).toLowerCase().includes(query));

  $("#app").innerHTML = `
    <section class="page-head">
      <h1>${escapeHtml(category)}</h1>
      <p class="muted">${query ? `「${escapeHtml(query)}」の検索結果: ` : ""}${list.length}件</p>
    </section>
    ${list.length
      ? `<div class="product-grid">${list.map(productCard).join("")}</div>`
      : `<p class="empty">該当する商品が見つかりませんでした。</p>`}`;
}

function renderProduct(id) {
  renderCategoryNav();
  const p = PRODUCTS.find((x) => x.id === Number(id));
  if (!p) return render404();
  const soldOut = p.stock <= 0;
  $("#app").innerHTML = `
    <a href="javascript:history.back()" class="back-link">← 戻る</a>
    <section class="product-detail">
      <div class="detail-image">${p.image}</div>
      <div class="detail-info">
        <p class="muted small">${escapeHtml(p.category)}</p>
        <h1>${escapeHtml(p.name)}</h1>
        <p class="price large">${yen(p.price)}<span class="muted small">（税込）</span></p>
        <p>${escapeHtml(p.description)}</p>
        <p class="${soldOut ? "stock-out" : "stock-ok"}">${soldOut ? "在庫切れ" : `在庫あり（残り ${p.stock} 点）`}</p>
        <div class="qty-row">
          <label for="qty">数量</label>
          <input type="number" id="qty" min="1" max="${p.stock}" value="1" ${soldOut ? "disabled" : ""}>
        </div>
        <button class="btn btn-primary btn-lg" data-add="${p.id}" data-with-qty ${soldOut ? "disabled" : ""}>
          ${soldOut ? "在庫切れ" : "カートに入れる"}
        </button>
      </div>
    </section>`;
}

function renderCart() {
  renderCategoryNav();
  const items = Cart.detailed();
  if (items.length === 0) {
    $("#app").innerHTML = `
      <h1>ショッピングカート</h1>
      <p class="empty">カートは空です。</p>
      <a href="#/" class="btn btn-primary">買い物を続ける</a>`;
    return;
  }
  const subtotal = Cart.subtotal();
  const shipping = Cart.shipping();
  $("#app").innerHTML = `
    <h1>ショッピングカート</h1>
    <div class="cart-layout">
      <ul class="cart-items">
        ${items.map((p) => `
          <li class="cart-item">
            <div class="cart-thumb">${p.image}</div>
            <div class="cart-item-info">
              <a href="#/product/${p.id}" class="product-name">${escapeHtml(p.name)}</a>
              <p class="price">${yen(p.price)}</p>
              <div class="qty-control">
                <button data-dec="${p.id}" aria-label="減らす">−</button>
                <span>${p.qty}</span>
                <button data-inc="${p.id}" aria-label="増やす" ${p.qty >= p.stock ? "disabled" : ""}>＋</button>
              </div>
            </div>
            <div class="cart-item-right">
              <p class="price">${yen(p.price * p.qty)}</p>
              <button class="link-btn" data-remove="${p.id}">削除</button>
            </div>
          </li>`).join("")}
      </ul>
      <aside class="summary">
        <h2>注文概要</h2>
        <div class="row"><span>小計</span><span>${yen(subtotal)}</span></div>
        <div class="row"><span>送料</span><span>${shipping === 0 ? "無料" : yen(shipping)}</span></div>
        ${shipping > 0 ? `<p class="muted small">${yen(FREE_SHIPPING_THRESHOLD - subtotal)} 以上の購入で送料無料</p>` : ""}
        <div class="row total"><span>合計（税込）</span><span>${yen(subtotal + shipping)}</span></div>
        <a href="#/checkout" class="btn btn-primary btn-block">レジに進む</a>
      </aside>
    </div>`;
}

function renderCheckout() {
  renderCategoryNav();
  const items = Cart.detailed();
  if (items.length === 0) { location.hash = "#/cart"; return; }
  const subtotal = Cart.subtotal();
  const shipping = Cart.shipping();
  $("#app").innerHTML = `
    <h1>ご注文手続き</h1>
    <div class="cart-layout">
      <form id="checkout-form" class="checkout-form" novalidate>
        <fieldset>
          <legend>お届け先</legend>
          <label>お名前 <input name="name" required autocomplete="name"></label>
          <label>メールアドレス <input name="email" type="email" required autocomplete="email"></label>
          <label>電話番号 <input name="phone" type="tel" required autocomplete="tel"></label>
          <label>郵便番号 <input name="zip" required pattern="\\d{3}-?\\d{4}" placeholder="123-4567" autocomplete="postal-code"></label>
          <label>住所 <input name="address" required autocomplete="street-address"></label>
        </fieldset>
        <fieldset>
          <legend>お支払い方法</legend>
          <label class="radio"><input type="radio" name="payment" value="card" checked> クレジットカード（デモ）</label>
          <label class="radio"><input type="radio" name="payment" value="cod"> 代金引換</label>
        </fieldset>
        <p class="error" id="form-error" role="alert"></p>
        <button type="submit" class="btn btn-primary btn-block">注文を確定する（${yen(subtotal + shipping)}）</button>
      </form>
      <aside class="summary">
        <h2>注文内容</h2>
        ${items.map((p) => `<div class="row small"><span>${escapeHtml(p.name)} × ${p.qty}</span><span>${yen(p.price * p.qty)}</span></div>`).join("")}
        <hr>
        <div class="row"><span>小計</span><span>${yen(subtotal)}</span></div>
        <div class="row"><span>送料</span><span>${shipping === 0 ? "無料" : yen(shipping)}</span></div>
        <div class="row total"><span>合計</span><span>${yen(subtotal + shipping)}</span></div>
      </aside>
    </div>`;

  $("#checkout-form").addEventListener("submit", (e) => {
    e.preventDefault();
    const form = e.target;
    const data = Object.fromEntries(new FormData(form).entries());
    const err = validateCheckout(data);
    if (err) { $("#form-error").textContent = err; return; }
    placeOrder(data, items, subtotal, shipping);
  });
}

function validateCheckout(d) {
  if (!d.name?.trim()) return "お名前を入力してください。";
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email || "")) return "メールアドレスの形式が正しくありません。";
  if (!/^0\d{1,4}-?\d{1,4}-?\d{3,4}$/.test(d.phone || "")) return "電話番号の形式が正しくありません。";
  if (!/^\d{3}-?\d{4}$/.test(d.zip || "")) return "郵便番号の形式が正しくありません（例: 123-4567）。";
  if (!d.address?.trim()) return "住所を入力してください。";
  return null;
}

function placeOrder(customer, items, subtotal, shipping) {
  // 在庫を減算（デモ：メモリ上の PRODUCTS のみ更新）
  items.forEach((p) => {
    const product = PRODUCTS.find((x) => x.id === p.id);
    if (product) product.stock -= p.qty;
  });
  const orderNo = "ORD-" + Date.now().toString(36).toUpperCase();
  const orders = JSON.parse(localStorage.getItem("shopeasy_orders") || "[]");
  orders.push({ orderNo, date: new Date().toISOString(), customer: { ...customer, payment: undefined }, items: items.map(({ id, name, price, qty }) => ({ id, name, price, qty })), total: subtotal + shipping });
  localStorage.setItem("shopeasy_orders", JSON.stringify(orders));
  Cart.clear();

  $("#app").innerHTML = `
    <section class="complete">
      <h1>ご注文ありがとうございます！</h1>
      <p>注文番号: <strong>${orderNo}</strong></p>
      <p>${escapeHtml(customer.email)}宛に確認メールを送信しました（デモ）。</p>
      <p>合計: <strong>${yen(subtotal + shipping)}</strong></p>
      <a href="#/" class="btn btn-primary">トップへ戻る</a>
    </section>`;
  window.scrollTo(0, 0);
}

function render404() {
  renderCategoryNav();
  $("#app").innerHTML = `<h1>ページが見つかりません</h1><a href="#/">トップへ戻る</a>`;
}

// ===== ルーター（ハッシュベース） =====
function route() {
  const hash = location.hash || "#/";
  const [path, query] = hash.slice(1).split("?");
  const params = new URLSearchParams(query || "");
  const parts = path.split("/").filter(Boolean);

  if (parts.length === 0) renderHome(params);
  else if (parts[0] === "product" && parts[1]) renderProduct(parts[1]);
  else if (parts[0] === "cart") renderCart();
  else if (parts[0] === "checkout") renderCheckout();
  else render404();

  window.scrollTo(0, 0);
}

// ===== イベント（イベント委譲） =====
document.addEventListener("click", (e) => {
  const addBtn = e.target.closest("[data-add]");
  if (addBtn) {
    const id = Number(addBtn.dataset.add);
    let qty = 1;
    if (addBtn.hasAttribute("data-with-qty")) qty = Math.max(1, parseInt($("#qty")?.value, 10) || 1);
    Cart.add(id, qty);
    return;
  }
  const inc = e.target.closest("[data-inc]");
  if (inc) {
    const id = Number(inc.dataset.inc);
    const item = Cart.load().find((i) => i.id === id);
    Cart.setQty(id, (item?.qty || 0) + 1);
    return renderCart();
  }
  const dec = e.target.closest("[data-dec]");
  if (dec) {
    const id = Number(dec.dataset.dec);
    const item = Cart.load().find((i) => i.id === id);
    Cart.setQty(id, (item?.qty || 0) - 1);
    return renderCart();
  }
  const rm = e.target.closest("[data-remove]");
  if (rm) {
    Cart.remove(Number(rm.dataset.remove));
    return renderCart();
  }
});

$("#search-form").addEventListener("submit", (e) => {
  e.preventDefault();
  const q = $("#search-input").value.trim();
  location.hash = "#/?q=" + encodeURIComponent(q);
});

window.addEventListener("hashchange", route);
window.addEventListener("storage", updateCartBadge);

// ===== 初期化 =====
updateCartBadge();
route();

