:root {
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --text: #1f2937;
  --muted: #6b7280;
  --border: #e5e7eb;
  --bg: #f9fafb;
  --danger: #dc2626;
  --ok: #16a34a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", system-ui, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

main { flex: 1; width: 100%; padding-top: 24px; padding-bottom: 48px; }
.container { max-width: 1100px; margin: 0 auto; padding: 0 16px; }
h1 { font-size: 1.6rem; margin: 0 0 16px; }
h2 { font-size: 1.1rem; margin: 0 0 12px; }
a { color: var(--primary); text-decoration: none; }
a:hover { text-decoration: underline; }
.muted { color: var(--muted); }
.small { font-size: 0.85rem; }
.large { font-size: 1.5rem; }
.empty { padding: 40px 0; text-align: center; color: var(--muted); }

/* ヘッダー */
.site-header { background: #fff; border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 10; }
.header-inner { display: flex; align-items: center; gap: 16px; padding-top: 12px; padding-bottom: 12px; }
.logo { font-size: 1.4rem; font-weight: 700; color: var(--text); white-space: nowrap; }
.search-form { flex: 1; display: flex; max-width: 480px; margin-left: auto; }
.search-form input { flex: 1; padding: 8px 12px; border: 1px solid var(--border); border-radius: 6px 0 0 6px; font-size: 1rem; }
.search-form button { padding: 8px 16px; border: 1px solid var(--primary); background: var(--primary); color: #fff; border-radius: 0 6px 6px 0; cursor: pointer; }
.cart-link { font-size: 1.3rem; color: var(--text); position: relative; white-space: nowrap; }
.badge { display: inline-block; min-width: 20px; padding: 0 6px; font-size: 0.75rem; line-height: 20px; text-align: center; background: var(--danger); color: #fff; border-radius: 10px; vertical-align: top; }

.category-nav { border-top: 1px solid var(--border); background: #fff; }
.category-nav .container { display: flex; gap: 20px; overflow-x: auto; padding-top: 8px; padding-bottom: 8px; }
.category-nav a { color: var(--text); white-space: nowrap; padding: 4px 0; }
.category-nav a.active { color: var(--primary); font-weight: 700; border-bottom: 2px solid var(--primary); }

/* 商品一覧 */
.page-head { margin-bottom: 16px; }
.product-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; }
.product-card { background: #fff; border: 1px solid var(--border); border-radius: 10px; overflow: hidden; display: flex; flex-direction: column; }
.product-thumb { display: flex; align-items: center; justify-content: center; height: 140px; font-size: 64px; background: #f3f4f6; text-decoration: none; }
.product-info { padding: 12px; display: flex; flex-direction: column; gap: 4px; flex: 1; }
.product-name { color: var(--text); font-weight: 600; }
.price { font-weight: 700; margin: 4px 0; }
.product-info .btn { margin-top: auto; }

/* ボタン */
.btn { display: inline-block; padding: 8px 16px; border-radius: 6px; border: 1px solid var(--border); background: #fff; color: var(--text); font-size: 0.95rem; cursor: pointer; text-align: center; }
.btn:hover { text-decoration: none; }
.btn-primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); }
.btn-primary:disabled { background: #9ca3af; border-color: #9ca3af; cursor: not-allowed; }
.btn-lg { padding: 12px 24px; font-size: 1.05rem; }
.btn-block { display: block; width: 100%; margin-top: 12px; }
.link-btn { background: none; border: none; color: var(--danger); cursor: pointer; padding: 0; font-size: 0.9rem; }

/* 商品詳細 */
.back-link { display: inline-block; margin-bottom: 16px; }
.product-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; background: #fff; padding: 24px; border-radius: 10px; border: 1px solid var(--border); }
.detail-image { display: flex; align-items: center; justify-content: center; font-size: 160px; background: #f3f4f6; border-radius: 10px; min-height: 320px; }
.stock-ok { color: var(--ok); font-weight: 600; }
.stock-out { color: var(--danger); font-weight: 600; }
.qty-row { display: flex; align-items: center; gap: 12px; margin: 16px 0; }
.qty-row input { width: 80px; padding: 6px; border: 1px solid var(--border); border-radius: 6px; }

/* カート */
.cart-layout { display: grid; grid-template-columns: 2fr 1fr; gap: 24px; align-items: start; }
.cart-items { list-style: none; padding: 0; margin: 0; background: #fff; border: 1px solid var(--border); border-radius: 10px; }
.cart-item { display: flex; gap: 16px; padding: 16px; border-bottom: 1px solid var(--border); }
.cart-item:last-child { border-bottom: none; }
.cart-thumb { width: 80px; height: 80px; display: flex; align-items: center; justify-content: center; font-size: 40px; background: #f3f4f6; border-radius: 8px; flex-shrink: 0; }
.cart-item-info { flex: 1; }
.cart-item-right { text-align: right; display: flex; flex-direction: column; justify-content: space-between; align-items: flex-end; }
.qty-control { display: inline-flex; align-items: center; gap: 8px; margin-top: 6px; }
.qty-control button { width: 28px; height: 28px; border: 1px solid var(--border); background: #fff; border-radius: 4px; cursor: pointer; }
.qty-control button:disabled { opacity: 0.4; cursor: not-allowed; }

.summary { background: #fff; border: 1px solid var(--border); border-radius: 10px; padding: 20px; }
.summary .row { display: flex; justify-content: space-between; margin: 8px 0; }
.summary .row.total { font-size: 1.15rem; font-weight: 700; border-top: 1px solid var(--border); padding-top: 12px; margin-top: 12px; }
.summary hr { border: none; border-top: 1px solid var(--border); margin: 12px 0; }

/* チェックアウト */
.checkout-form { background: #fff; border: 1px solid var(--border); border-radius: 10px; padding: 20px; }
.checkout-form fieldset { border: 1px solid var(--border); border-radius: 8px; margin: 0 0 16px; padding: 12px 16px; }
.checkout-form legend { font-weight: 700; padding: 0 6px; }
.checkout-form label { display: block; margin: 8px 0; font-size: 0.95rem; }
.checkout-form input:not([type="radio"]) { display: block; width: 100%; margin-top: 4px; padding: 8px; border: 1px solid var(--border); border-radius: 6px; font-size: 1rem; }
.checkout-form label.radio { display: flex; align-items: center; gap: 8px; }
.checkout-form label.radio input { width: auto; margin: 0; }
.error { color: var(--danger); min-height: 1.4em; }
.complete { background: #fff; border: 1px solid var(--border); border-radius: 10px; padding: 32px; text-align: center; }

/* フッター */
.site-footer { background: #111827; color: #d1d5db; padding: 24px 0; text-align: center; font-size: 0.9rem; }
.site-footer .muted { color: #9ca3af; }

/* トースト */
.toast { position: fixed; left: 50%; bottom: 24px; transform: translate(-50%, 120%); background: #111827; color: #fff; padding: 12px 20px; border-radius: 8px; transition: transform .3s; pointer-events: none; max-width: 90%; }
.toast.show { transform: translate(-50%, 0); }

/* レスポンシブ */
@media (max-width: 760px) {
  .header-inner { flex-wrap: wrap; }
  .search-form { order: 3; max-width: none; width: 100%; margin-left: 0; }
  .product-detail, .cart-layout { grid-template-columns: 1fr; }
  .detail-image { min-height: 200px; font-size: 100px; }
}
